//! Excluded actual-gallery grouped worklist and native disclosure/selection workflows.
use super::grid_worklist_review::gallery_worklist;
use dioxus::prelude::*;
use dioxus_ix::*;

#[component]
pub fn GridGroupPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_worklist::STYLES} }
        IxTheme { class:"grid-group-review",
            gallery_worklist::GridWorklistExample {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_GRID_GROUP_CHECK);let _=query.send("gridgroups");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Grid groups: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Grid groups failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(40)).await;eprintln!("Grid groups native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
const STYLES: &str = "body{margin:0}.grid-group-review{box-sizing:border-box;min-height:100vh;padding:24px}@media(max-width:600px){.grid-group-review{padding:16px}}";

